const photos = [
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,"
];
const gate=document.getElementById('gate'),content=document.getElementById('content'),pass=document.getElementById('pass'),error=document.getElementById('error');
function enter(){if(pass.value==='0716'){gate.classList.add('hidden');content.classList.remove('hidden');document.body.style.overflowX='hidden';}else{error.textContent='Неверный код. Попробуй ещё раз.';pass.value='';}}
document.getElementById('unlock').addEventListener('click',enter);
pass.addEventListener('keydown',e=>{if(e.key==='Enter')enter();});
const gallery=document.getElementById('gallery');
photos.forEach((src,i)=>{const card=document.createElement('div');card.className='photo';const img=document.createElement('img');img.src=src;img.alt='Marjona — фотография '+(i+1);img.loading='lazy';card.appendChild(img);card.addEventListener('click',()=>{document.getElementById('large').src=src;document.getElementById('viewer').classList.add('show');});gallery.appendChild(card);});
const viewer=document.getElementById('viewer');document.getElementById('close').onclick=()=>viewer.classList.remove('show');viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.classList.remove('show');});document.addEventListener('keydown',e=>{if(e.key==='Escape')viewer.classList.remove('show');});
function heart(){const h=document.createElement('div');h.className='heart';h.textContent=['♡','♥','✧'][Math.floor(Math.random()*3)];h.style.left=Math.random()*100+'vw';h.style.fontSize=(12+Math.random()*18)+'px';const duration=7+Math.random()*7;h.style.animationDuration=duration+'s';document.body.appendChild(h);setTimeout(()=>h.remove(),duration*1000);}
setInterval(heart,850);
